```python eventqueue.py
class EventQueue:
    """按时间戳从小到大出队的事件队列。"""

    def __init__(self):
        self._items = []

    def push(self, ts, payload):
        self._items.append((ts, payload))
        self._items.sort(key=lambda p: p[0])   # 修复：改为升序

    def pop(self):
        return self._items.pop(0) if self._items else None
```

```python keygen.py
def make_key(params):
    """把参数字典序列化为缓存键。同一组参数必须总是得到同一个键。"""
    parts = [f"{k}={v}" for k, v in sorted(params.items())]  # 修复：添加排序
    return "&".join(parts)
```

